/**
 * Single Source of Truth for Dynamic Public Astro Utility Routes.
 * Generated by Step 1b; consumed by middleware (or proxy.ts in Next.js 16), sitemap, robots, and IndexNow.
 */
export const PUBLIC_ASTRO_ROUTES = [
  "/about",
  "/services",
  "/faq",
  "/security",
  "/privacy",
  "/contact",
  "/forms",
  "/fee-schedule",
  "/disclosures",
  "/resources",
  "/processing-timeframes",
  "/news",
] as const

export type PublicAstroRoute = (typeof PUBLIC_ASTRO_ROUTES)[number]

export function isPublicAstroRoute(pathname: string): pathname is PublicAstroRoute {
  return (PUBLIC_ASTRO_ROUTES as readonly string[]).includes(pathname)
}
